import sys

def main():
    import sys
    import math
    n = int(sys.stdin.read().strip())
    result = []

    # Initial placement strategy
    if n == 1:
        result.append((0, 0))
    elif n == 2:
        result.append((0, 0))
        result.append((2, 0))
    elif n == 3:
        result.append((0, 0))
        result.append((2 * 2, 0))
        result.append((2 * 2 + 1, 0))
    else:
        # Use a grid pattern with some adjustments
        row, col = 0, 0
        for i in range(n):
            result.append((row, col))
            if (row + col) % 2 == 0:
                col += 2
            else:
                row += 2
            if col >= 2 * n:
                row += 2
                col = 0

    for x, y in result:
        print(x, y)

if __name__ == "__main__":
    main()
